'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { BarChart3, AlertTriangle } from 'lucide-react';

export default function DeptStatsPage() {
    const [stats, setStats] = useState<any>(null);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await api.get<any>('/api/hod/department/stats');
                if (res.success) setStats(res.data);
            } catch (e) { }
        };
        load();
    }, []);

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                Department Statistics
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>Monitor department performance and attendance defaulters</p>

            {!stats ? (
                <div className="card" style={{ textAlign: 'center', padding: 48, color: '#8a9aa2' }}>
                    <BarChart3 size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p>Loading department statistics...</p>
                </div>
            ) : (
                <>
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 24 }}>
                        <div className="card" style={{ padding: 24 }}>
                            <div style={{ fontSize: 13, color: '#8a9aa2', marginBottom: 8 }}>Total Students Tracked</div>
                            <div style={{ fontSize: 28, fontWeight: 800, color: '#142B34', fontFamily: 'Poppins' }}>
                                {stats.total_students_tracked}
                            </div>
                        </div>
                        <div className="card" style={{ padding: 24, borderLeft: '4px solid #ef4444' }}>
                            <div style={{ fontSize: 13, color: '#8a9aa2', marginBottom: 8 }}>Attendance Defaulters (&lt;75%)</div>
                            <div style={{ fontSize: 28, fontWeight: 800, color: '#ef4444', fontFamily: 'Poppins' }}>
                                {stats.defaulters.length}
                            </div>
                        </div>
                    </div>

                    {stats.defaulters.length > 0 && (
                        <div className="card" style={{ padding: 24 }}>
                            <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}>
                                <AlertTriangle size={18} color="#ef4444" /> Defaulter List
                            </h3>
                            <div className="table-container">
                                <table>
                                    <thead><tr><th>Student ID</th><th>Attendance %</th><th>Present</th><th>Total Sessions</th></tr></thead>
                                    <tbody>
                                        {stats.defaulters.map((d: any, i: number) => (
                                            <tr key={i}>
                                                <td style={{ fontWeight: 600 }}>{d.student_id}</td>
                                                <td style={{ color: '#ef4444', fontWeight: 700 }}>{d.attendance_percentage}%</td>
                                                <td>{d.present}</td>
                                                <td>{d.total_sessions}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}
                </>
            )}
        </div>
    );
}
